with open(VENUS_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    pisces_json = "      Pisces: " + json.dumps(pisces_data, indent=8) + ","
    new_content = content[:insertion_point] + "\n" + pisces_json + content[insertion_point:]
    
    with open(VENUS_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Venus in Pisces to venus.js")
else:
    print("Could not find signs object in venus.js")
